#include <algorithm>
#include <cstdint>

// 예제: 실게임의 전투 상태 머신에 전달할 조절값
struct AttackRule {
    float startupSec = 0.22f;    // 공격 준비: 이 기간에 피격될 수 있음
    float activeSec = 0.10f;     // 유효 판정이 살아 있는 시간
    float recoverySec = 0.32f;   // 공격 후 빈틈
    int damageOnHit = 28;
    int pointsOnHit = 100;
};

enum class AttackPhase { Idle, Startup, Active, Recovery };

struct AttackState {
    AttackPhase phase = AttackPhase::Idle;
    float phaseTime = 0.f;
    bool rewardGranted = false;
    std::uint32_t attackId = 0;
};

void BeginAttack(AttackState& s) {
    if (s.phase != AttackPhase::Idle) return;
    s.phase = AttackPhase::Startup;
    s.phaseTime = 0.f;
    s.rewardGranted = false;
    ++s.attackId;
}

// 단순한 단계별 상태 갱신 예시: 한 프레임에서 여러 상태를
// 건너뛰지 않도록 고정 tick 또는 잔여시간 루프를 사용하는 것이 좋다.
void UpdatePhase(AttackState& s, const AttackRule& rule, float dt) {
    s.phaseTime += std::max(0.f, dt);
    if (s.phase == AttackPhase::Startup && s.phaseTime >= rule.startupSec) {
        s.phase = AttackPhase::Active;
        s.phaseTime = 0.f;
    } else if (s.phase == AttackPhase::Active && s.phaseTime >= rule.activeSec) {
        s.phase = AttackPhase::Recovery;
        s.phaseTime = 0.f;
    } else if (s.phase == AttackPhase::Recovery && s.phaseTime >= rule.recoverySec) {
        s.phase = AttackPhase::Idle;
        s.phaseTime = 0.f;
    }
}

// Hit 시스템이 '검증된 단일 타격'에 대해 한 번만 호출한다.
bool TryGrantReward(AttackState& s) {
    if (s.phase != AttackPhase::Active || s.rewardGranted) return false;
    s.rewardGranted = true; // 실제 지급 전에 중복 차단
    return true;
}

#include <algorithm>

// y는 위쪽이 양수, bulletSpeed는 초당 월드 유닛
float PredictEnemyX(float playerY,
                    float enemyY,
                    float enemyX,
                    float enemyVelocityX,
                    float bulletSpeed) {
    if (bulletSpeed <= 0.f) return enemyX;
    const float verticalDistance = std::max(0.f, enemyY - playerY);
    const float flightTime = verticalDistance / bulletSpeed;
    return enemyX + enemyVelocityX * flightTime;
}
